SELECT COALESCE(NULLIF(drama_type, ''), '未知类型') AS labelName, COUNT(1) AS totalCount, COALESCE(SUM(play_count), 0) AS totalPlayCount, ROUND(COALESCE(AVG(play_count), 0), 2) AS avgPlayCount, ROUND(COALESCE(AVG(score), 0), 2) AS avgScore, ROUND(COALESCE(SUM(like_count) * 100.0 / NULLIF(SUM(IFNULL(like_count, 0) + IFNULL(negative_count, 0)), 0), 0), 2) AS positiveRate, ROUND(COALESCE(SUM(negative_count) * 100.0 / NULLIF(SUM(IFNULL(like_count, 0) + IFNULL(negative_count, 0)), 0), 0), 2) AS negativeRate, ROUND(COALESCE(COUNT(1) * 100.0 / NULLIF((SELECT COUNT(1) FROM
), 0), 0), 2) AS ratio FROM
GROUP BY COALESCE(NULLIF(drama_type, ''), '未知类型') ORDER BY totalPlayCount DESC, totalCount DESC LIMIT 20

SELECT segmentName, COUNT(1) AS totalCount, COALESCE(SUM(play_count), 0) AS totalPlayCount, ROUND(COALESCE(AVG(play_count), 0), 2) AS avgPlayCount, ROUND(COALESCE(AVG(score), 0), 2) AS avgScore, ROUND(COALESCE(AVG(like_count), 0), 2) AS avgLikeCount, ROUND(COALESCE(AVG(negative_count), 0), 2) AS avgNegativeCount, ROUND(COALESCE(SUM(like_count) * 100.0 / NULLIF(SUM(IFNULL(like_count, 0) + IFNULL(negative_count, 0)), 0), 0), 2) AS positiveRate, ROUND(COALESCE(COUNT(1) * 100.0 / NULLIF((SELECT COUNT(1) FROM
), 0), 0), 2) AS ratio FROM ( SELECT CASE WHEN score IS NULL THEN '未知评分' WHEN score < 6 THEN '6分以下' WHEN score < 7 THEN '6-7分' WHEN score < 8 THEN '7-8分' WHEN score < 9 THEN '8-9分' ELSE '9分及以上' END AS segmentName, CASE WHEN score IS NULL THEN 99 WHEN score < 6 THEN 1 WHEN score < 7 THEN 2 WHEN score < 8 THEN 3 WHEN score < 9 THEN 4 ELSE 5 END AS sortNo, play_count, like_count, negative_count, score FROM
) t GROUP BY segmentName, sortNo ORDER BY sortNo ASC

SELECT segmentName, COUNT(1) AS totalCount, COALESCE(SUM(play_count), 0) AS totalPlayCount, ROUND(COALESCE(AVG(play_count), 0), 2) AS avgPlayCount, ROUND(COALESCE(AVG(score), 0), 2) AS avgScore, ROUND(COALESCE(SUM(like_count) * 100.0 / NULLIF(SUM(IFNULL(like_count, 0) + IFNULL(negative_count, 0)), 0), 0), 2) AS positiveRate, ROUND(COALESCE(COUNT(1) * 100.0 / NULLIF((SELECT COUNT(1) FROM
), 0), 0), 2) AS ratio FROM ( SELECT CASE WHEN play_count IS NULL THEN '未知播放量' WHEN play_count < 10000000 THEN '1000万以下' WHEN play_count < 50000000 THEN '1000-5000万' WHEN play_count < 100000000 THEN '5000万-1亿' WHEN play_count < 500000000 THEN '1-5亿' ELSE '5亿以上' END AS segmentName, CASE WHEN play_count IS NULL THEN 99 WHEN play_count < 10000000 THEN 1 WHEN play_count < 50000000 THEN 2 WHEN play_count < 100000000 THEN 3 WHEN play_count < 500000000 THEN 4 ELSE 5 END AS sortNo, play_count, like_count, negative_count, score FROM
) t GROUP BY segmentName, sortNo ORDER BY sortNo ASC
